97	async function waitForReachable(baseUrl: string, timeoutMs = 180_000): Promise<void> {
98	  const start = Date.now();
99	  let lastError: unknown;
100	  while (Date.now() - start < timeoutMs) {
101	    try {
102	      const res = await httpFetch(`${baseUrl}/server/ping`);
103	      if (res.ok) return;
104	    } catch (error) {
105	      lastError = error;
106	    }
107	    await new Promise((resolve) => setTimeout(resolve, 5_000));
108	  }
109	  throw new Error(
110	    `Directus at ${baseUrl} did not become reachable within ${timeoutMs}ms (VM boot/DNS/TLS may still be in ` +
111	      `progress — re-run \`pulumi up\` once it's up). Last error: ${String(lastError)}`,
112	  );
113	}
