115	async function login(baseUrl: string, email: string, password: string): Promise<string> {
116	  const res = await httpFetch(`${baseUrl}/auth/login`, {
117	    method: "POST",
118	    headers: { "Content-Type": "application/json" },
119	    body: JSON.stringify({ email, password }),
120	  });
121	  if (!res.ok) {
122	    throw new Error(`Directus login as ${email} failed: ${res.status} ${await res.text()}`);
123	  }
124	  return ((await res.json()) as { data: { access_token: string } }).data.access_token;
125	}
