127	async function directusRequest<T>(
128	  baseUrl: string,
129	  token: string,
130	  method: string,
131	  path: string,
132	  body?: unknown,
133	): Promise<T> {
134	  const res = await httpFetch(`${baseUrl}${path}`, {
135	    method,
136	    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
137	    body: body !== undefined ? JSON.stringify(body) : undefined,
138	  });
139	  if (!res.ok) {
140	    throw new Error(`${method} ${path} -> ${res.status}: ${await res.text()}`);
141	  }
142	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
143	}
